CREATE   PROCEDURE [synapse_ce].[usp_Insert_apuk_location]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_location]
	(
		[apuk_addresscity],
		[apuk_addresscountryid],
		[apuk_addresscountryid_entitytype],
		[apuk_addresscountryidname],
		[apuk_addresscounty],
		[apuk_addresspostcode],
		[apuk_addressstreet1],
		[apuk_addressstreet2],
		[apuk_addressstreet3],
		[apuk_keycontactid],
		[apuk_keycontactid_entitytype],
		[apuk_keycontactidname],
		[apuk_keycontactidyominame],
		[apuk_locationid],
		[apuk_name],
		[apuk_organisationalunitid],
		[apuk_organisationalunitid_entitytype],
		[apuk_organisationalunitidname],
		[apuk_venuename],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[overriddencreatedon],
		[ownerid],
		[ownerid_entitytype],
		[owneridname],
		[owneridtype],
		[owneridyominame],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owningbusinessunitname],
		[owningteam],
		[owningteam_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apuk_addresscity],
		stg.[apuk_addresscountryid],
		stg.[apuk_addresscountryid_entitytype],
		stg.[apuk_addresscountryidname],
		stg.[apuk_addresscounty],
		stg.[apuk_addresspostcode],
		stg.[apuk_addressstreet1],
		stg.[apuk_addressstreet2],
		stg.[apuk_addressstreet3],
		stg.[apuk_keycontactid],
		stg.[apuk_keycontactid_entitytype],
		stg.[apuk_keycontactidname],
		stg.[apuk_keycontactidyominame],
		stg.[apuk_locationid],
		stg.[apuk_name],
		stg.[apuk_organisationalunitid],
		stg.[apuk_organisationalunitid_entitytype],
		stg.[apuk_organisationalunitidname],
		stg.[apuk_venuename],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[overriddencreatedon],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[owneridname],
		stg.[owneridtype],
		stg.[owneridyominame],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owningbusinessunitname],
		stg.[owningteam],
		stg.[owningteam_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_location] stg
		LEFT JOIN [synapse_ce].[apuk_location] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
